struct AdapterService: Service {
    let control: ChannelHandler                     // swift-nio control listener on its own port

    func run() async throws {
        try await withThrowingTaskGroup(of: Void.self) { group in
            group.addTask { try await serveData() }
            group.addTask { try await serveControl(on: control) }   // suspend/status/shutdown
            try await group.next()                                 // first child ends...
            group.cancelAll()                                      // ...then the rest is cancelled
        }
    }
}

let group = ServiceGroup(services: [AdapterService()], logger: logger)
try await group.run()

